<section>
    <div class="section-heading"><div><p class="eyebrow">Estrutura competitiva</p><h1>Fases</h1><p>Configure grupos antes de publicar a fase.</p></div></div>
    <?php if (!empty($message)): ?><p class="success" role="status"><?= App\Core\View::e($message) ?></p><?php endif; ?>
    <form method="get" class="filters"><label>Campeonato <select name="championship_id" onchange="this.form.submit()"><option value="">Selecione</option><?php foreach ($championships as $championship): ?><option value="<?= (int) $championship['id'] ?>" <?= (int) $championship_id === (int) $championship['id'] ? 'selected' : '' ?>><?= App\Core\View::e($championship['name']) ?></option><?php endforeach; ?></select></label></form>
    <?php if ($canCreate && $championship_id): ?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><input type="hidden" name="championship_id" value="<?= (int) $championship_id ?>"><label>Nome <input name="name" required value="Fase de grupos"></label><label>Slug <input name="slug" required value="fase-grupos"></label><label>Grupos <input type="number" name="group_count" min="1" value="2" required></label><label>Equipes por grupo <input type="number" name="teams_per_group" min="2" value="5" required></label><label>Classificados por grupo <input type="number" name="qualified_per_group" min="1" value="4" required></label><button type="submit">Criar fase</button></form><?php endif; ?>
    <div class="stack-list"><?php foreach ($phases as $phase): ?><article class="panel"><header><h2><?= App\Core\View::e($phase['name']) ?></h2><span class="status status-<?= App\Core\View::e($phase['status']) ?>"><?= App\Core\View::e($phase['status']) ?></span></header><p><?= (int) $phase['groups_count'] ?> grupos, <?= (int) $phase['teams_count'] ?> equipes, <?= (int) $phase['qualified_per_group'] ?> classificados por grupo.</p><p><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/grupos?phase_id=' . $phase['id'])) ?>">Gerenciar grupos</a> | <a href="<?= App\Core\View::e(App\Core\Config::url('/admin/tabela/assistente?phase_id=' . $phase['id'])) ?>">Abrir assistente</a></p><?php if ($phase['status'] === 'draft'): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/fases/' . $phase['id'] . '/publicar')) ?>"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><button type="submit">Publicar fase</button></form><?php elseif ($phase['status'] === 'published'): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/fases/' . $phase['id'] . '/iniciar')) ?>"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><button type="submit">Iniciar fase</button></form><?php endif; ?></article><?php endforeach; ?></div>
</section>
